        int a = in.nextInt();
        int b = in.nextInt();
        int l = in.nextInt() - 1;
        int r = in.nextInt() - 1;       
        int ans;
        int len = a + b;
        int dif = r - l;
        if(dif >= 2 * len) {
            ans = Integer.max(a + 1, 2 * a - b);
        } else {
            //shift to the left
            r -= len * (l / len);
            l %= len;
            //System.out.println(l + " " + r);
            ans = numOfDifLet(a, b, l, r);
        }

        System.out.println(ans);

    }

    static int numOfDifLet(int a, int b, int l, int r) {
        int first = b < a ? b : a - 1;
        int last = a - 1;

        // abcd dd abef ff
        // abcd cc abef ff abcd dd abef ff

        StringBuilder sb = new StringBuilder();
        char ch = 'a';
        for(int i = 0; i < a; ++i) {
